        gl.bindBuffer(gl.ARRAY_BUFFER, boxBuf);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(pos), gl.DYNAMIC_DRAW);
        gl.bindBuffer(gl.ARRAY_BUFFER, boxColBuf);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(col), gl.DYNAMIC_DRAW);
        run({ mode: gl.LINES, n: pos.length / 3, p: boxBuf, nn: null, c: boxColBuf, lit: 0, alpha: 1 });
      } else if (scene.frame !== false) {
        const c = ink(), col = [];
        for (let i = 0; i < framePos.length / 3; i++) col.push(...c);
        gl.bindBuffer(gl.ARRAY_BUFFER, frameCol);
        gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(col), gl.DYNAMIC_DRAW);
        gl.enable(gl.BLEND);
        gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
        run({ mode: gl.LINES, n: framePos.length / 3, p: frameBuf, nn: null, c: frameCol, lit: 0, alpha: 0.45 });
      }
      gl.enable(gl.BLEND);
      gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
      gl.depthMask(false);
      for (const d of draws) if (d.alpha < 1) run(d);
      // volumes last, over the rest (premultiplied colors)
      for (const v of vols) {
        gl.useProgram(v.vp.p);
        gl.uniformMatrix4fv(v.vp.M, false, new Float32Array(M));
        gl.uniformMatrix4fv(v.vp.P, false, new Float32Array(P));
        gl.uniform3fv(v.vp.eye, eye);
        gl.uniform3fv(v.vp.bmin, v.bmin);
        gl.uniform3fv(v.vp.bmax, v.bmax);
        gl.uniform1f(v.vp.samples, v.samples);
        gl.uniform1f(v.vp.alphaCoef, v.alphaCoef);
        gl.activeTexture(gl.TEXTURE0);
        gl.bindTexture(gl.TEXTURE_3D, v.tex);
        gl.uniform1i(v.vp.vol, 0);
        gl.activeTexture(gl.TEXTURE1);
        gl.bindTexture(gl.TEXTURE_2D, v.lut);
        gl.uniform1i(v.vp.lut, 1);
        gl.bindBuffer(gl.ARRAY_BUFFER, v.box);
        gl.vertexAttribPointer(v.vp.ap, 3, gl.FLOAT, false, 0, 0);
        gl.enableVertexAttribArray(v.vp.ap);
        gl.enable(gl.CULL_FACE);
        gl.cullFace(gl.FRONT); // the back faces: rays from the eye even inside the box
        gl.disable(gl.DEPTH_TEST);
        gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
        gl.drawArrays(gl.TRIANGLES, 0, 36);
        gl.disable(gl.CULL_FACE);
        gl.enable(gl.DEPTH_TEST);
        gl.useProgram(prog.p);
      }
      gl.depthMask(true);
      placeLabels(M, P);
      snapshot();
    }

    // screen position (CSS pixels) of a display point
    const screen = (M, P, p) => {
      const q = apply(P, apply(M, p));
      return [(q[0] / q[3] + 1) * W / 2, (1 - q[1] / q[3]) * H / 2, q[2] / q[3]];
    };

    // the box edge each axis's tick labels go on: the lowest on the screen
    // for x and y, the leftmost for z (nearer the viewer breaking ties)
    function pickEdges(M, P) {
      const pts = {};
      for (const i of [0, 1]) for (const j of [0, 1]) for (const k of [0, 1]) pts[[i, j, k]] = screen(M, P, C(i, j, k));
      const all = Object.values(pts), cx = all.reduce((s, p) => s + p[0], 0) / 8, cy = all.reduce((s, p) => s + p[1], 0) / 8;
      const best = [];
      for (let axis = 0; axis < 3; axis++) {
        let pick = null, score = -Infinity;
        for (const [s, t, ax] of edges) {
          if (ax !== axis) continue;
          const a = pts[s], b = pts[t], m = [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2];
          const sc = (axis !== 2 ? m[1] - cy : cx - m[0]) - 40 * ((a[2] + b[2]) / 2);
          if (sc > score) { score = sc; pick = { ends: [a, b], edge: [s, t] }; }
        }
        best.push(pick);
      }
      return { cx, cy, best };
    }

    function placeLabels(M, P) {
      let n = 0;
      const put = (x, y, text, style, z) => {
        if (!(z > -1 && z < 1)) return; // behind the eye (flying)
        const s = label(n++);
        s.style.left = x + "px"; s.style.top = y + "px"; s.style.display = "";
        setRich(s, text);
        s.style.fontStyle = style?.italic ? "italic" : "";
        s.style.fontSize = style?.size ? style.size + "px" : "";
        s.style.color = style?.color || "";
      };
      for (const t of geo.texts) { const p = screen(M, P, t.at); put(p[0], p[1], t.text, { size: t.size || 12, color: t.color }, p[2]); }
      if (scene.frame !== false || mbox) {
        const { cx, cy, best: chosen } = pickEdges(M, P);
        for (let axis = 0; axis < 3; axis++) {
          const [a, b] = chosen[axis].ends, lo = scene.lo[axis], hi = scene.hi[axis];
          const mx = (a[0] + b[0]) / 2, my = (a[1] + b[1]) / 2, dl = Math.hypot(mx - cx, my - cy) || 1;
          const ox = (mx - cx) / dl, oy = (my - cy) / dl;
          // (MATLAB's axes: its tick values and labels; else round ones)
          const nt = mbox ? null : niceTicks(lo, hi, 4);
          const vals = mbox ? mbox.ticks[axis] || [] : nt.ticks;
          vals.forEach((v, k) => {
            if (typeof v !== "number" || v < lo - 1e-9 * (hi - lo) || v > hi + 1e-9 * (hi - lo)) return;
            const f = hi > lo ? (v - lo) / (hi - lo) : 0.5;
            const given = mbox && Array.isArray(mbox.ticklabels) && Array.isArray(mbox.ticklabels[axis]) ? mbox.ticklabels[axis][k] : undefined;
            const text = mbox ? given ?? tickLabel(v, Math.abs(hi - lo) / 10 || 1) : tickLabel(v, nt.step);
            put(a[0] + (b[0] - a[0]) * f + 14 * ox, a[1] + (b[1] - a[1]) * f + 12 * oy, text, null, Math.max(a[2], b[2]));
          });
          const name = (scene.labels || [])[axis];
          if (name) put(mx + 34 * ox, my + 30 * oy, mbox ? name : axisLabel(name), mbox ? { size: 11 } : { italic: true, size: 12 }, Math.max(a[2], b[2]));
        }
      }
      for (let i = n; i < labels.length; i++) labels[i].style.display = "none";
    }

    // ---- navigation: orbit (default) and fly, with smooth motion.
    // Orbit: drag rotates about the target (with inertia), right- or
    // shift-drag pans, the wheel zooms toward the cursor, a double-click
    // glides to orbit the point under it.  Fly (F): mouse look (pointer
    // lock), W A S D / arrows, Space or E up, Q or C down, Shift faster,
    // wheel sets the speed; a gamepad flies too.  Keys work in both modes.
    let raf = 0, lastT = 0, fly = false, spin = null, auto = false, tween = null, speed = 1;
    let vel = [0, 0, 0];
    const keys = new Set();
    const clampEl = (e) => Math.max(-89, Math.min(89, e));
    const redraw = () => { if (!raf && canvas.isConnected) raf = requestAnimationFrame(tick); };
    // turn about the eye (fly) or about the target (orbit)
    function look(daz, del) {
      const { eye, dist } = camera();
      view.az += daz; view.el = clampEl(view.el + del);
      const d = dirOf(view.az, view.el);
      view.t = [eye[0] - dist * d[0], eye[1] - dist * d[1], eye[2] - dist * d[2]];
    }
    function orbit(daz, del) { view.az += daz; view.el = clampEl(view.el + del); }
    // the ray through the CSS pixel (x, y)
    function ray(x, y) {
      const c = camera(), th = Math.tan(fov / 2), px = (2 * x / W - 1) * th * (W / H), py = (1 - 2 * y / H) * th;
      if (ortho) {
        // (parallel rays: from the point of the eye's plane under the cursor)
        const s = halfH(), o = [0, 1, 2].map((i) => c.eye[i] + (px / th) * s * c.r[i] + (py / th) * s * c.u[i] - 20 * c.f[i]);
        return { o, dir: c.f, c };
      }
      return { o: c.eye, dir: unit([0, 1, 2].map((i) => c.f[i] + px * c.r[i] + py * c.u[i])), c };
    }
    // the nearest surface point on a ray (Moller-Trumbore), else the
    // middle of its run through a volume, else null
    function pick(x, y) {
      const { o, dir } = ray(x, y);
      let best = Infinity;
      const tri = (P, a, b, c) => {
        const e1x = P[b] - P[a], e1y = P[b + 1] - P[a + 1], e1z = P[b + 2] - P[a + 2];
        const e2x = P[c] - P[a], e2y = P[c + 1] - P[a + 1], e2z = P[c + 2] - P[a + 2];
        const px = dir[1] * e2z - dir[2] * e2y, py = dir[2] * e2x - dir[0] * e2z, pz = dir[0] * e2y - dir[1] * e2x;
        const det = e1x * px + e1y * py + e1z * pz;
        if (Math.abs(det) < 1e-12) return;
        const inv = 1 / det, sx = o[0] - P[a], sy = o[1] - P[a + 1], sz = o[2] - P[a + 2];
        const u = (sx * px + sy * py + sz * pz) * inv;
        if (u < 0 || u > 1) return;
        const qx = sy * e1z - sz * e1y, qy = sz * e1x - sx * e1z, qz = sx * e1y - sy * e1x;
        const v = (dir[0] * qx + dir[1] * qy + dir[2] * qz) * inv;
        if (v < 0 || u + v > 1) return;
        const t = (e2x * qx + e2y * qy + e2z * qz) * inv;
        if (t > 1e-4 && t < best) best = t;
      };
      for (const t of geo.tris) for (let i = 0; i + 8 < t.pos.length; i += 9) tri(t.pos, i, i + 3, i + 6);
      for (const m of geo.meshes) for (let i = 0; i + 2 < m.idx.length; i += 3) tri(m.pos, 3 * m.idx[i], 3 * m.idx[i + 1], 3 * m.idx[i + 2]);
