        for (const v of geo.volumes) {
          let tn = 0, tf = Infinity;
          for (let i = 0; i < 3; i++) {
            const a = (v.bmin[i] - o[i]) / dir[i], b = (v.bmax[i] - o[i]) / dir[i];
            tn = Math.max(tn, Math.min(a, b)); tf = Math.min(tf, Math.max(a, b));
