      const inp = [0, 0, 0];
      const k = (c) => keys.has(c) ? 1 : 0;
      inp[0] = k("KeyD") - k("KeyA");
      inp[1] = k("KeyE") + k("Space") - k("KeyQ") - k("KeyC");
      inp[2] = k("KeyW") - k("KeyS");
