        if (fly) { const c = camera(); view.t = view.t.map((x, i) => x + c.f[i] * Math.log(r) * 2 * speed); }
        else view.zoom = Math.min(ZMAX, Math.max(ZMIN, view.zoom * r));
        two = q;
