        if (drag.pan && !fly) pan(dx, dy);
        else if (fly) look(dx * 0.25, dy * 0.25);
        else {
          orbit(-dx * 0.5, dy * 0.5);
          const t = performance.now(), ms = Math.max(1, t - drag.at);
          drag.v = [0.7 * drag.v[0] + 0.3 * (-dx * 0.5 * 1000 / ms), 0.7 * drag.v[1] + 0.3 * (dy * 0.5 * 1000 / ms)];
          drag.at = t;
        }
